const props = defineProps({ tab: String, data: Object, query: Object, applied: Object, options: Object })
const emit = defineEmits(['rows', 'profile', 'evidence', 'action', 'apply', 'tab'])
const trendMetric = ref('business_order_amount'), productDimension = ref('craft'), trendDimension = ref('province'), trendMode = ref('value'), customerSearch = ref(''), customerSelection = ref([]), peopleSelection = ref([])
watch(() => props.data.meta.run_id, () => { customerSelection.value = []; peopleSelection.value = [] })
const productFields = ['product_type', 'craft', 'net_color', 'size', 'length', 'density', 'hair_style_series', 'color']
const overviewCards = computed(() => [{ key: 'business_order_amount', label: '业务下单金额', format: 'money', icon: Money, note: '正常业务单，按下单日期统计' }, { key: 'shipped_amount', label: '发货出库金额', format: 'money', icon: Goods, tone: 'success', note: '有效发货完成报工数量 × 成交单价' }, { key: 'recharge_amount', label: '客户充值金额', format: 'money', icon: Wallet, tone: 'info', note: !props.data.finance ? '需要资金阅读权限' : props.applied.finance_related_customers ? '按本次相关客户实际充值入账' : '客户范围实际充值，忽略产品筛选' }, { key: 'customer_count', label: '下单客户个数', icon: UserFilled, tone: 'violet', note: '统计周期内同一客户只计一次' }])
const financeCards = [{ key: 'recharge_amount', label: '已入账充值', format: 'money', icon: Wallet, note: '仅正向充值流水' }, { key: 'net_order_deduction', label: '订单净扣款', format: 'money', icon: Tickets, tone: 'info', note: '退款与调整独立核对' }, { key: 'positive_balance', label: '正余额合计', format: 'money', icon: Money, tone: 'success', note: '已知余额，异常需另核验' }, { key: 'debt', label: '欠款合计', format: 'money', icon: TrendCharts, tone: 'warning', note: '负余额绝对值' }]
const col = (key, text, format, extra = {}) => ({ key, label: text, format, ...extra })
const trendColumns = [col('date', '日期'), col('business_order_amount', '业务下单金额', 'money'), col('shipped_amount', '发货出库金额', 'money'), col('recharge_amount', '客户充值金额', 'money'), col('quantity', '下单件数', 'number'), col('customer_count', '下单客户个数', 'number')]
const dimensionColumns = [col('label', '属性'), col('amount', '匹配额', 'money'), col('quantity', '数量', 'number'), col('order_count', '订单数', 'number'), col('customer_count', '客户数', 'number'), col('share', '金额占比', 'percent'), col('previous_amount', '对照金额', 'money'), col('amount_change.rate', '金额变化率', 'percent')]
const matrixColumns = [col('x', '维度一'), col('y', '维度二'), col('amount', '匹配额', 'money'), col('quantity', '数量', 'number'), col('order_count', '订单数', 'number'), col('customer_count', '客户数', 'number')]
const productColumns = [...productFields.map(field => col(`attrs.${field}`, FIELD_LABELS[field])), col('amount', '匹配额', 'money'), col('quantity', '数量', 'number'), col('order_count', '订单数', 'number'), col('customer_count', '客户数', 'number')]
const priceBandColumns = [col('band', '成交单价带'), col('amount', '金额', 'money'), col('quantity', '数量', 'number'), col('item_count', '明细数', 'number')]
const itemQuantityColumns = [col('band', '每行件数'), col('item_count', '明细行数', 'number'), col('quantity', '匹配数量', 'number'), col('amount', '匹配明细金额', 'money')]
const orderQuantityColumns = [col('band', '整单总件数'), col('order_count', '相关订单数', 'number'), col('whole_quantity', '整单全部数量', 'number'), col('matched_quantity', '筛选命中数量', 'number'), col('related_order_amount', '相关整单金额', 'money')]
