const customerCompareColumns = [...customerColumns, col('history.purchase_days', '历史购买日', 'number'), col('history.system_amount', '系统累计额', 'money'), col('history.archival_amount', '档案累计额', 'money'), col('history.rfm.status', 'RFM样本状态')]
const peopleColumns = [col('name', '负责人'), col('portfolio_customer_count', '归属客户', 'number'), col('active_customer_count', '当期购买客户', 'number'), col('amount', '当前组合整单额', 'money'), col('quantity', '数量', 'number'), col('order_count', '订单数', 'number')]
const financeCustomerColumns = [col('shop_name', '客户', null, { link: true }), col('opening_balance', '期初余额', 'money'), col('closing_balance', '期末余额', 'money'), col('recharge_amount', '充值额', 'money'), col('net_order_deduction', '净订单扣款', 'money'), col('debt', '欠款', 'money'), col('pending_recharge_amount', '待审核', 'money'), col('coverage_days', '余额覆盖天数', 'number'), col('coverage_status', '覆盖指标状态'), col('recharge_cycle_days', '充值周期天数', 'number'), col('reliable', '账链可靠', null, { get: row => row.reliable ? '可靠' : '异常待核验' })]
const waitingColumns = [col('customer_id', '客户ID'), col('ledger_id', '充值流水ID'), col('next_order_id', '后续订单ID'), col('first_purchase_wait_days', '等待天数', 'number'), col('status', '观察状态')]
const pendingWaitColumns = [col('request_id', '申请ID'), col('customer_id', '客户ID'), col('wait_seconds', '等待秒数', 'number')]
const reviewColumns = [col('reviewed_count', '完成审核', 'number'), col('median_review_seconds', '审核中位秒数', 'number'), col('p90_review_seconds', '审核P90秒数', 'number'), { key: 'pending', label: '待审核', format: 'number', get: row => row.pending?.length }]
const cohortColumns = [col('month', '首购/充值月份'), col('window_days', '观察天数', 'number'), col('mature_count', '成熟样本', 'number'), { key: 'purchase_count', label: '后续购买', format: 'number', get: row => row.purchase_count ?? row.second_purchase_count }, col('rate', '观察购买率', 'percent'), col('immature_count', '尚未成熟', 'number')]
const customers = computed(() => props.data.customers.filter(row => `${row.shop_name} ${row.province} ${row.city}`.includes(customerSearch.value.trim())))
const financeCustomers = computed(() => (props.data.finance?.customers || []).map(row => ({ ...row, shop_name: row.shop_name || props.data.customers.find(customer => customer.customer_id === row.customer_id)?.shop_name || `客户 ${row.customer_id}` })))
const bridgeRows = computed(() => Object.entries(props.data.finance?.summary.bridge_components || {}).map(([key, value]) => ({ label: { recharge: '充值', order_charge: '订单扣款', order_adjustment_positive: '正向订单调整', order_adjustment_negative: '负向订单调整', order_refund: '退款', init: '期初初始化', adjust: '人工调整', level_adjust: '等级调整' }[key] || key, amount: ['order_charge', 'order_adjustment_negative'].includes(key) ? -value : value })))
const trendRows = computed(() => (props.data.dimensions[trendDimension.value] || []).map(row => ({ ...row, amount_delta: row.amount_change?.absolute ?? null })))
const concentration = computed(() => { const rows = props.data.dimensions[trendDimension.value] || []; const sum = rows.reduce((total, row) => total + row.amount, 0); return sum > 0 ? [...rows].sort((a, b) => b.amount - a.amount).slice(0, 3).reduce((total, row) => total + row.amount, 0) / sum : null })
const unknownShare = computed(() => { const rows = props.data.dimensions[trendDimension.value] || [], sum = rows.reduce((total, row) => total + row.amount, 0); return sum > 0 ? rows.filter(row => /未知|待映射|未归类/.test(row.label)).reduce((total, row) => total + row.amount, 0) / sum : null })
function observations(groups) { return (groups || []).flatMap(group => (group.observations || []).map(row => ({ ...row, month: group.month }))) }
const buyingCohortRows = computed(() => Array.isArray(props.data.cohorts) ? props.data.cohorts.flatMap(group => (group.observations || []).map(row => ({ ...row, month: group.month }))) : observations(props.data.cohorts?.monthly))
const financeCohortRows = computed(() => observations(props.data.finance?.cohorts?.monthly))
function toggleSelection(list, id) { const index = list.indexOf(id); if (index >= 0) list.splice(index, 1); else if (list.length < 4) list.push(id) }
function dimensionDrill(field, row) { emit('rows', 'items', { dimension: field, value: row.key }, `${FIELD_LABELS[field]}：${row.label} · 匹配明细`) }
function matrixDrill(row) { emit('evidence', row.evidence_refs) }
function trendDrill(row) {
  const type = trendMetric.value === 'shipped_amount' ? 'reports' : trendMetric.value === 'recharge_amount' ? 'ledger' : 'orders'
  const records = (props.data.evidence[type] || []).filter(item => type === 'reports' ? item.process_name === '发货完成' && item.reported_at?.slice(0, 10) === row.date : type === 'ledger' ? item.transaction_type === 'recharge' && item.amount > 0 && item.created_at?.slice(0, 10) === row.date : item.order_date === row.date)
  emit('evidence', records.map(item => ({ type, id: item.id })))
}
</script>
